<template><div class="register-page"><div class="register-card"><h2>辅导员注册</h2><el-form :model="form" :rules="rules" ref="formRef" label-width="80px"><el-form-item label="用户名" prop="username"><el-input v-model="form.username"/></el-form-item><el-form-item label="密码" prop="password"><el-input v-model="form.password" type="password" show-password/></el-form-item><el-form-item label="姓名" prop="name"><el-input v-model="form.name"/></el-form-item><el-form-item label="性别"><el-select v-model="form.gender" style="width:100%"><el-option label="男" value="男"/><el-option label="女" value="女"/></el-select></el-form-item><el-form-item label="学院"><el-select v-model="form.collegeId" style="width:100%"><el-option v-for="c in colleges" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="政治面貌"><el-select v-model="form.politicalStatus" style="width:100%"><el-option v-for="p in politicalStatuses" :key="p" :label="p" :value="p"/></el-select></el-form-item><el-form-item label="最高学历"><el-select v-model="form.highestEducation" style="width:100%"><el-option v-for="e in educations" :key="e" :label="e" :value="e"/></el-select></el-form-item><el-form-item label="办公地址"><el-input v-model="form.officeAddress"/></el-form-item><el-form-item label="电话"><el-input v-model="form.phone"/></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email"/></el-form-item><el-form-item><el-button type="primary" @click="register" :loading="loading" style="width:100%">提交注册申请</el-button></el-form-item></el-form><div class="links"><router-link to="/login">已有账号？立即登录</router-link><el-button text type="primary" @click="statusVisible=true">查询审核结果</el-button></div></div><el-dialog v-model="statusVisible" title="查询注册审核结果" width="min(92%,420px)"><el-form label-position="top"><el-form-item label="用户名"><el-input v-model="queryForm.username"/></el-form-item><el-form-item label="密码"><el-input v-model="queryForm.password" type="password" show-password/></el-form-item></el-form><el-alert v-if="queryResult" :title="statusText(queryResult.status)" :description="queryResult.comment||''" :type="queryResult.status==='REJECTED'?'error':queryResult.status==='ACTIVE'?'success':'info'" show-icon :closable="false"/><template #footer><el-button @click="statusVisible=false">关闭</el-button><el-button type="primary" @click="queryStatus">查询</el-button></template></el-dialog></div></template>
<script setup>import{reactive,ref,onMounted}from'vue';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';import api from'../../utils/request';const router=useRouter(),formRef=ref(),loading=ref(false),colleges=ref([]),statusVisible=ref(false),queryResult=ref(null),queryForm=reactive({username:'',password:''});const politicalStatuses=['中共党员','中共预备党员','共青团员','群众','民主党派'],educations=['博士','硕士','本科','大专'];const form=reactive({username:'',password:'',name:'',gender:'',collegeId:null,politicalStatus:'',highestEducation:'',officeAddress:'',phone:'',email:''});const rules={username:[{required:true,message:'请输入用户名'},{min:3,max:50,message:'3-50个字符'}],password:[{required:true,message:'请输入密码'},{min:6,message:'不少于6个字符'}],name:[{required:true,message:'请输入姓名'}]};onMounted(async()=>{colleges.value=(await api.get('/public/colleges')).data});async function register(){if(!await formRef.value.validate().catch(()=>false))return;loading.value=true;try{await api.post('/auth/counselor/register',form);ElMessage.success('申请已提交，请等待管理员审核');router.push('/login')}finally{loading.value=false}}async function queryStatus(){queryResult.value=(await api.post('/auth/counselor/registration-status',queryForm)).data;if(queryResult.value.status==='REJECTED'){form.username=queryForm.username;form.password=queryForm.password;ElMessage.info('请修改资料后重新提交注册申请')}}function statusText(v){return({PENDING_REVIEW:'审核中，请耐心等待',ACTIVE:'审核已通过，可以登录',REJECTED:'注册申请已驳回',DISABLED:'账号已禁用'})[v]||v}</script>
<style scoped>.register-page{min-height:100vh;display:flex;align-items:center;justify-content:center;background:#edf2f7;padding:20px}.register-card{width:460px;padding:32px 40px;background:#fff;border-radius:8px;box-shadow:0 4px 24px rgba(0,0,0,.12)}.register-card h2{text-align:center}.links{display:flex;align-items:center;justify-content:center;gap:12px}@media(max-width:540px){.register-card{width:100%;padding:24px 16px}}</style>
